changeSet.sql:
ALTER TABLE "${database.defaultSchemaName}".tenant ADD CONSTRAINT ck_tenant_id CHECK (id ~ '^[a-z][a-z0-9_]{0,62}$');
ALTER TABLE "${database.defaultSchemaName}".tenant ADD CONSTRAINT ck_tenant_schema_name
CHECK (schema_name ~ '^[a-z][a-z0-9_]{0,62}$');
ALTER TABLE "${database.defaultSchemaName}".tenant ADD CONSTRAINT ck_tenant_status CHECK (status IN ('ACTIVE', 'SUSPENDED'));
ALTER TABLE "${database.defaultSchemaName}".tenant ADD CONSTRAINT ck_tenant_pool_max_size CHECK (pool_max_size > 0);
